import pRetry, {AbortError} from 'p-retry';

const body = await pRetry(async attempt => {
    const res = await fetch(url, {signal});
    if (res.status === 404) throw new AbortError('gone');       // permanent
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
}, {retries: 3, minTimeout: 200, factor: 2, randomize: true, signal});

